// Reverse function with efficient implementation
function reverse<T>(s: seq<T>): seq<T>
  ensures |reverse(s)| == |s|
  ensures forall i: int :: 0 <= i < |s| ==> reverse(s)[i] == s[|s| - 1 - i]
  ensures reverse(reverse(s)) == s
{
  if |s| == 0 then []
  else if |s| == 1 then [s[0]]
  else [s[|s|-1]] + reverse(s[0..|s|-1])
}

// Lemma to prove that reverse distributes over concatenation
lemma ReverseAppendDistr<T>(s1: seq<T>, s2: seq<T>)
  ensures reverse(s1 + s2) == reverse(s2) + reverse(s1)
{
  // Proof by induction on s1
  if |s1| == 0 {
    // Base case: empty sequence
    assert reverse([] + s2) == reverse(s2);
    assert reverse(s2) + reverse([]) == reverse(s2) + [];
    assert reverse(s2) + [] == reverse(s2);
  } else {
    // Inductive step
    var x := s1[0];
    var rest := s1[1..];
    calc {
      reverse(s1 + s2);
      == reverse([x] + rest + s2);
      == reverse([x] + (rest + s2));
      == reverse(rest + s2) + [x];
      == { ReverseAppendDistr(rest, s2); }
      (reverse(s2) + reverse(rest)) + [x];
      == reverse(s2) + (reverse(rest) + [x]);
      == reverse(s2) + reverse([x] + rest);
      == reverse(s2) + reverse(s1);
    }
  }
}

// Lemma to prove that reverse is an involution (applying it twice gives original)
lemma ReverseInvolution<T>(s: seq<T>)
  ensures reverse(reverse(s)) == s
{
  // This is already part of the function's postcondition, but we prove it explicitly
  if |s| == 0 {
    // Base case
    assert reverse(reverse([])) == reverse([]) == [];
  } else if |s| == 1 {
    // Single element case
    assert reverse(reverse([s[0]])) == reverse([s[0]]) == [s[0]];
  } else {
    // General case using the recursive definition
    var last := s[|s|-1];
    var rest := s[0..|s|-1];
    calc {
      reverse(reverse(s));
      == reverse([last] + reverse(rest));
      == { ReverseAppendDistr([last], reverse(rest)); }
      reverse(reverse(rest)) + reverse([last]);
      == { ReverseInvolution(rest); }
      rest + [last];
      == s[0..|s|-1] + [s[|s|-1]];
      == s;
    }
  }
}

// Additional lemma for slicing property mentioned in instructions
lemma ReverseSlice<T>(s: seq<T>, k: int)
  requires 0 <= k <= |s|
  ensures reverse(s[k..]) == reverse(s)[0..|s|-k]
{
  // This lemma relates reverse of a slice to slice of reverse
  if k == |s| {
    // Empty slice case
    assert s[k..] == [];
    assert reverse([]) == [];
    assert |s| - k == 0;
    assert reverse(s)[0..0] == [];
  } else {
    // Non-empty case - proof by induction on s
    var x := s[k];
    var rest := s[k+1..];
    calc {
      reverse(s[k..]);
      == reverse([x] + rest);
      == reverse(rest) + [x];
      == { ReverseSlice(s, k+1); }
      reverse(s)[0..|s|-(k+1)] + [x];
      == reverse(s)[0..|s|-k-1] + [reverse(s)[|s|-k-1]];
      == reverse(s)[0..|s|-k];
    }
  }
